/* GOAL 5 · Configurator skin · channel 3514134. Step strip, hero car (SVG silhouette recoloured by the answers), option subtitles/swatches,
   "Your configuration" bar with a Next CTA (pick a card → preview in the hero → Next sends it). Keys 1–9 / A–Z pick, Enter = Next.
   2026-09-28: English end to end (was Italian); every matcher below equals the English flow copy.
   Reads the DOM only; the only thing it ever sends is a click on the flow's own buttons.
   HERO PHOTOS (2026-09-18): 3 AI-generated studio photos of a fictional, unbranded white car (one per version) + a paint mask + a highlight map,
   embedded below as data URIs (~45 KB per car). Colour = a CSS layer multiplied over the photo inside the mask, so the car never moves when the
   colour changes. WHAT is paint comes from a flat-magenta colour-ID pass of each photo made by the same image model (work-goal5/img/id-*.png), registered to the photo by work-goal5/mask3.py. Built with build_config_js.py. No real brand assets. */
(function(){
  try {
    if (window.__lbFootRan) return; window.__lbFootRan = true;
    /* STATE — recomputed from the thread on every tick. Back posts a "Back" user message and re-sends the earlier question,
       so nothing here counts messages: the step is the LAST question on screen, and an answer is the LAST one given to that question. */
    var BACK='Back', SKIP={'Start':1,'Start again':1};
    /* curly quotes and runs of spaces are folded so "What's" matches however the renderer prints it */
    function norm(s){ return String(s||'').replace(/[\u2018\u2019]/g,"'").replace(/\s+/g,' ').trim(); }
    var QS=[
      {k:'model',q:'Which model are you interested in?',t:'Model',opts:['Kestrel City','Kestrel Tourer','Kestrel Cross']},
      {k:'colour',q:'Pick a colour',t:'Colour',opts:['Midnight blue','Coral red','Pearl white','Graphite black']},
      {k:'fuel',q:'Which powertrain do you prefer?',t:'Powertrain',opts:['Electric','Hybrid','Petrol']},
      {k:'timeline',q:'When are you planning to buy?',t:'Timeline',opts:['Within 1 month','Within 3 months','Within 6 months','Just researching']},
      {k:'postcode',q:"What's your postcode?",t:'Postcode'},
      {k:'name',q:"What's your name?",t:'Name'},{k:'phone',q:'What number can we call you back on?',t:'Phone'},
      {k:'email',q:'And your email?',t:'Email'},{k:'privacy',q:'I agree to the processing',t:'Privacy',opts:['I agree',"I don't agree"]}];
    var STEPS=5;
    function readState(){
      var cur=-1, ans={}, done=false, welcome=true;
      [].forEach.call(document.querySelectorAll('[data-lb-part="message"]'), function(m){
        var el=m.querySelector('[data-lb-part="message-text"]'); if(!el) return; var t=norm(el.textContent); if(!t) return;
        if (m.getAttribute('data-lb-author')==='bot') {
          if (t.indexOf('Your Kestrel')===0) { cur=-1; ans={}; done=false; welcome=true; return; }
          for (var i=0;i<QS.length;i++) if (t.indexOf(QS[i].q)===0) { cur=i; done=false; welcome=false; for (var j=i+1;j<QS.length;j++) delete ans[QS[j].k]; return; }
          if (t.indexOf('Your configuration')===0 || t.indexOf('Without your consent')===0) { done=true; welcome=false; }
        } else {
          if (t===BACK || SKIP[t]) return;
          for (var o=0;o<QS.length;o++) if (QS[o].opts && QS[o].opts.indexOf(t)>=0) { ans[QS[o].k]=t; return; }
          if (cur>=0 && !QS[cur].opts) ans[QS[cur].k]=t;
        }
      });
      return {cur:cur, ans:ans, done:done, welcome:welcome};
    }
    var SUB={'Kestrel City':'Compact and nimble in town','Kestrel Tourer':'Estate for the whole family','Kestrel Cross':'SUV with a raised ride',
             'Electric':'Plugs in to charge','Hybrid':'Petrol and electric together','Petrol':'Classic engine'};
    /* label: [swatch key, swatch hex, tint multiplied over the photo, highlight-layer opacity] */
    var COL={'Midnight blue':['blue','#1d3557','#223f67',0.55],'Coral red':['red','#d9503f','#ff5e4a',0.30],'Pearl white':['white','#f2f2ef','#fdfbf6',0],'Graphite black':['black','#2a2a2a','#2e2e30',0.80]};
    var NOCOLOR='#c3c6cc';   /* before a colour is chosen: neutral silver, so that picking Pearl white is a visible change */
    var IMG={"city": {"base": "data:image/webp;base64,", "mask": "data:image/webp;base64,", "spec": "data:image/webp;base64,"}, "tourer": {"base": "data:image/webp;base64,", "mask": "data:image/webp;base64,", "spec": "data:image/webp;base64,"}, "cross": {"base": "data:image/webp;base64,", "mask": "data:image/webp;base64,", "spec": "data:image/webp;base64,"}};
    var MODEL={'Kestrel City':'city','Kestrel Tourer':'tourer','Kestrel Cross':'cross'};
    var NEXT=['Colour','Powertrain','Timeline','Postcode','Your details','Phone','Email','Privacy','Send request'];
    var esc=function(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]})};

    var strip=document.createElement('div'); strip.id='lb-strip'; strip.innerHTML='<div><span>Configure your Kestrel</span><span class="lb-step"></span></div>';
    var hero=document.createElement('div'); hero.id='lb-hero';
    hero.innerHTML='<div class="lb-hero-in"><div class="lb-panel"><span class="lb-badge"></span>'+
      '<div class="lb-photo"><img class="lb-base" alt=""><div class="lb-tint"></div><div class="lb-spec"></div></div>'+
      '<div class="lb-swatches">'+Object.keys(COL).map(function(c){return '<button type="button" class="lb-sw" data-c="'+esc(c)+'" aria-label="'+esc(c)+'" style="background:'+COL[c][1]+'"></button>'}).join('')+'</div>'+
      '<div class="lb-cap"></div></div></div>';
    var sum=document.createElement('div'); sum.id='lb-summary';
    sum.innerHTML='<div class="lb-sum-in"><div class="lb-sum-card"><div class="lb-sum-text"><span class="lb-sum-label">Your configuration</span><span class="lb-sum-val"></span></div><button type="button" id="lb-next"></button></div></div>';
    document.body.appendChild(strip); document.body.appendChild(hero); document.body.appendChild(sum);
    var elStep=strip.querySelector('.lb-step'), elBase=hero.querySelector('.lb-base'), elTint=hero.querySelector('.lb-tint'), elSpec=hero.querySelector('.lb-spec'), elCap=hero.querySelector('.lb-cap'),
        elBadge=hero.querySelector('.lb-badge'), elVal=sum.querySelector('.lb-sum-val'), next=sum.querySelector('#lb-next');

    var picked=null, pickedFor=-2, pass=false, last='';
    function opts(){ return [].slice.call(document.querySelectorAll('[data-lb-part="option-button"]')); }
    function label(b){ return norm(b.textContent); }
    function submitBtn(){ return document.querySelector('[data-lb-part="input-submit"], [data-lb-part="text-input"] button'); }
    function pick(b){ picked=label(b); render(true); }
    function send(){
      var s=readState(), o=opts();
      if (o.length===1) { pass=true; o[0].click(); pass=false; return; }
      if (o.length>1) { if(!picked) return; var b=o.filter(function(x){return label(x)===picked})[0]; if(b){ pass=true; b.click(); pass=false; picked=null; } return; }
      var sb=submitBtn(); if (sb) sb.click();
    }
    /* pick-then-Next: a tap on a card only selects it; the capture listener runs before React's root listener */
    document.addEventListener('click', function(e){
      if (pass) return; var b=e.target && e.target.closest && e.target.closest('[data-lb-part="option-button"]'); if(!b) return;
      if (opts().length<2) return; e.preventDefault(); e.stopPropagation(); pick(b);
    }, true);
    next.addEventListener('click', send);
    hero.addEventListener('click', function(e){ var sw=e.target.closest('.lb-sw'); if(!sw) return; var s=readState(); if (s.cur<0||QS[s.cur].k!=='colour') return;
      var b=opts().filter(function(x){return label(x)===sw.getAttribute('data-c')})[0]; if(b) pick(b); });
    document.addEventListener('keydown', function(e){
      var t=e.target, typing=t && (t.tagName==='INPUT'||t.tagName==='TEXTAREA'||t.isContentEditable); if (typing||e.metaKey||e.ctrlKey||e.altKey) return;
      if (e.key==='Enter') { send(); e.preventDefault(); return; }
      var k=(e.key||'').toUpperCase(), i=-1; if (k.length!==1) return;
      if (k>='A'&&k<='Z') i=k.charCodeAt(0)-65; else if (k>='1'&&k<='9') i=parseInt(k,10)-1;
      var o=opts(); if (i>=0 && o[i]) { if (o.length>1) pick(o[i]); else { pass=true; o[i].click(); pass=false; } e.preventDefault(); }
    }, true);

    function render(force){
      var s=readState(), o=opts();
      if (pickedFor!==s.cur) { picked=null; pickedFor=s.cur; }
      /* decorate the live cards every tick: v4 re-creates nodes, attributes go with them */
      o.forEach(function(b){ var l=label(b), sp=b.querySelector('span');
        if (sp && SUB[l] && sp.getAttribute('data-sub')!==SUB[l]) sp.setAttribute('data-sub',SUB[l]);
        if (COL[l] && b.getAttribute('data-swatch')!==COL[l][0]) b.setAttribute('data-swatch',COL[l][0]);
        if (l===picked) { if(!b.hasAttribute('data-lb-picked')) b.setAttribute('data-lb-picked','1'); } else if (b.hasAttribute('data-lb-picked')) b.removeAttribute('data-lb-picked'); });
      var inp=document.querySelector('[data-lb-part="text-input"] input');
      /* postcode: international (letters, digits, space, hyphen; the flow's pattern allows 3–10), so no numeric keyboard; attributes are removed on other steps */
      if (inp) { var pc = s.cur>=0 && QS[s.cur].k==='postcode';
        if (pc && inp.getAttribute('data-lb-pc')!=='1') { inp.setAttribute('data-lb-pc','1'); inp.setAttribute('maxlength','10'); inp.setAttribute('autocomplete','postal-code'); inp.setAttribute('autocapitalize','characters'); }
        else if (!pc && inp.getAttribute('data-lb-pc')==='1') { inp.removeAttribute('data-lb-pc'); inp.removeAttribute('maxlength'); inp.removeAttribute('autocomplete'); inp.removeAttribute('autocapitalize'); } }
      /* placeholders: the v4 chat hardcodes "Answer the question" / "Phone number" and ignores the block's own placeholder (web-chat bug, 2026-09-28),
         so set them here per step; re-applied every tick because a re-mounted input comes back with the default */
      var PH={postcode:'e.g. SW1A 1AA',name:'Your full name',phone:'Your phone number',email:'you@example.com'};
      if (inp) { var ph = s.cur>=0 && PH[QS[s.cur].k]; if (ph && inp.getAttribute('placeholder')!==ph) inp.setAttribute('placeholder',ph); }
      var view={}; for (var k in s.ans) view[k]=s.ans[k];
      if (picked && s.cur>=0) view[QS[s.cur].k]=picked;            /* preview the tapped card before it is sent */
      var sig=[s.cur,s.done,s.welcome,picked,o.length,!!inp,JSON.stringify(view)].join('|'); if (!force && sig===last) return; last=sig;
      document.body.classList.toggle('lb-done', s.done); document.body.classList.toggle('lb-welcome', s.welcome && !s.done);
      document.body.setAttribute('data-lb-step', s.cur>=0 ? QS[s.cur].k : ''); 
      elStep.textContent = s.done ? 'Complete' : s.cur<0 ? STEPS+' quick steps' : s.cur<STEPS ? 'Step '+(s.cur+1)+' of '+STEPS+' · '+QS[s.cur].t : 'Your details · '+QS[s.cur].t;
      var mk=MODEL[view.model]||'tourer', A=IMG[mk];
      if (A && hero.getAttribute('data-model')!==mk) { hero.setAttribute('data-model',mk); elBase.src=A.base;
        elTint.style.webkitMaskImage=elTint.style.maskImage='url('+A.mask+')'; elSpec.style.backgroundImage='url('+A.spec+')'; }
      var tint = view.colour ? COL[view.colour][2] : NOCOLOR; elTint.style.backgroundColor=tint; hero.setAttribute('data-tint',tint); elSpec.style.opacity = view.colour ? COL[view.colour][3] : 0.15;
      [].forEach.call(hero.querySelectorAll('.lb-sw'), function(x){ if (x.getAttribute('data-c')===view.colour) x.setAttribute('data-on','1'); else x.removeAttribute('data-on'); });
      elCap.textContent = [view.model||'Kestrel', view.colour].filter(Boolean).join(' · ');
      elBadge.textContent = view.fuel || '';
      var cfg=['model','colour','fuel','timeline','postcode'].map(function(k){return view[k]}).filter(Boolean);
      elVal.textContent = cfg.length ? cfg.join(' · ') : 'Five steps, no commitment';
      if (s.done) { next.hidden = true; next.textContent=''; }   /* the flow's own Start again button is on screen */
      else if (s.cur<0) { next.hidden=false; next.disabled = o.length!==1; next.textContent='Start'; }
      else { next.hidden=false; next.disabled = o.length>1 ? !picked : !(inp||o.length===1); next.textContent = s.cur===QS.length-1 ? NEXT[s.cur] : 'Next: '+NEXT[s.cur]; }
      document.documentElement.style.setProperty('--lb-bar-h', Math.ceil(sum.getBoundingClientRect().height)+'px');
    }
    render(); setInterval(render, 300);
    new MutationObserver(function(){ render(); }).observe(document.body,{childList:true,subtree:true});
    window.addEventListener('resize', function(){ render(true); });
    window.__lbState=function(){ var s=readState(); return {cur:s.cur, step:s.cur>=0?QS[s.cur].k:null, done:s.done, ans:s.ans, picked:picked, counter:elStep.textContent,
      heroFill:hero.getAttribute('data-tint'), heroShape:hero.getAttribute('data-model'), imgLoaded:!!(elBase.complete&&elBase.naturalWidth>0), imgW:elBase.naturalWidth, caption:elCap.textContent, badge:elBadge.textContent, summary:elVal.textContent, cta:next.hidden?null:next.textContent, ctaDisabled:next.disabled}; };
  } catch(err) { window.__lbFootErr = String(err); }
})();
